def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = []
    for i in range(n):
        a.append(int(input_data[i + 1]))

    # The candidate must be the minimum element because if x divides all elements,
    # then x <= any element, so x must be the minimum.
    candidate = min(a)

    # Check if candidate divides all elements
    for x in a:
        if x % candidate != 0:
            print(-1)
            return

    print(candidate)

